def count_vowels(s):
    v = 'аеёиоуыэюяaeiouy'
    return sum(1 for ch in s.lower() if ch in v)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def flatten(items):
    out = []
    for it in items:
        out.extend(it)
    return out

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

def unique_order(items):
    seen = []
    for it in items:
        if it not in seen:
            seen.append(it)
    return seen

def caesar(s, k):
    out = []
    for ch in s:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - 97 + k) % 26 + 97))
        elif 'A' <= ch <= 'Z':
            out.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            out.append(ch)
    return ''.join(out)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def strip_vowels(s):
    return ''.join(ch for ch in s
        if ch.lower() not in 'aeiouy')

def running_sum(nums):
    out, acc = [], 0
    for n in nums:
        acc += n
        out.append(acc)
    return out

def common(a, b):
    return [x for x in dict.fromkeys(a)
        if x in b]

def char_freq(s):
    out = {}
    for ch in s:
        out[ch] = out.get(ch, 0) + 1
    return out

def is_anagram(a, b):
    ka = sorted(ch.lower() for ch in a
        if ch.isalpha())
    kb = sorted(ch.lower() for ch in b
        if ch.isalpha())
    return ka == kb

def longest_word(s):
    words = s.split()
    best = words[0]
    for w in words[1:]:
        if len(w) > len(best):
            best = w
    return best

def snake_case(s):
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch.lower())
        else:
            out.append('_')
    return ''.join(out).strip('_').replace('__', '_')

def brackets_balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def missing_number(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def two_sum(nums, target):
    seen = set()
    for x in nums:
        if target - x in seen:
            return True
        seen.add(x)
    return False

def rotate(nums, k):
    if not nums:
        return []
    k = k % len(nums)
    return nums[-k:] + nums[:-k] if k else list(nums)

def count_inversions(nums):
    cnt = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                cnt += 1
    return cnt

def digit_root(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def vowel_start_words(text):
    return [w for w in text.split()
        if w and w[0].lower() in 'aeiouy']
